export type ContractName = keyof typeof CONTRACT_ERRORS;
export type ErrorName<C extends ContractName> = keyof (typeof CONTRACT_ERRORS)[C];
export type ErrorCode<C extends ContractName> = (typeof CONTRACT_ERRORS)[C][ErrorName<C>];
export type ContractError = { [C in ContractName]: {
  contract: C;
  name: ErrorName<C>;
  code: (typeof CONTRACT_ERRORS)[C][ErrorName<C>];
} }[ContractName];

export function isKnownContractError(contract: string, code: number): boolean {
  if (!(contract in CONTRACT_ERRORS)) return false;
  const errors = CONTRACT_ERRORS[contract as ContractName] as Record<string, number>;
  return Object.values(errors).includes(code);
}

export function contractErrorsForCode<C extends ContractName>(contract: C, code: number): ErrorName<C>[] {
  return Object.entries(CONTRACT_ERRORS[contract])
    .filter(([, errorCode]) => errorCode === code)
    .map(([name]) => name as ErrorName<C>);
}
